# K~(L^{2n+1}(m)) = Z[s]/(s^{n+1}, (1+s)^m - 1), s = chi - 1 (Atiyah Gysin/Thom iso, from memory)
# order of (1 - chi^{m/2}) as an element; integer HNF, exact.
from fractions import Fraction
from math import comb
def ideal_basis(n,m):
    # basis vectors in coords s^1..s^n of ideal generated by f=(1+s)^m-1 (truncated)
    f=[comb(m,j) for j in range(1,n+1)]  # coeff of s^j, j=1..n
    rows=[]
    for sh in range(n):
        v=[0]*n
        for j in range(n):
            if j+sh<n: v[j+sh]=f[j]
        rows.append(v)
    return rows
def in_lattice(rows,v):
    # rows upper triangular (shifted) with diagonal f[0]=m: solve triangular
    n=len(v); v=list(v)
    for i in range(n):
        piv=rows[i][i]
        if v[i]%piv: return False
        c=v[i]//piv
        v=[a-c*b for a,b in zip(v,rows[i])]
    return all(a==0 for a in v)
def elem(n,m,e):
    # chi^e - 1 = (1+s)^e - 1 truncated
    return [comb(e,j) for j in range(1,n+1)]
for m in (4,8):
  for n in range(1,16):
    rows=ideal_basis(n,m); x=elem(n,m,m//2)
    a=0
    while not in_lattice(rows,[ (2**a)*c for c in x]): a+=1
    print("m",m,"dim",2*n+1,"ord 2^",a," => k >=",a+1)
